#include "base/time/time.h"
// Copyright (c) 2026 VEOR Browser Authors. All rights reserved.  #include “autofill/AutofillStoreImpl.h”  #include <algorithm>  #include “core/logging/VeorLogger.h” #include “infrastructure/storage/IStorageEngine.h”  namespace veor {  namespace {  constexpr int kSchemaVersion = 1;  std::string EncryptField(ICryptoVault* crypto,                          const std::string& plaintext,                          const std::vector<uint8_t>& key) {   if (plaintext.empty())     return “”;   auto result = crypto->Encrypt(plaintext, key);   if (result.IsErr()) {     VEOR_LOGW(LogCategory::kSecurity,               “Autofill encryption failed: ” + result.UnwrapErr().message);     return “”;   }   auto& blob = result.Unwrap();   return std::string(blob.begin(), blob.end()); }  std::string DecryptField(ICryptoVault* crypto,                          const std::string& ciphertext,                          const std::vector<uint8_t>& key) {   if (ciphertext.empty())     return “”;   std::vector<uint8_t> blob(ciphertext.begin(), ciphertext.end());   auto result = crypto->Decrypt(blob, key);   if (result.IsErr()) {     VEOR_LOGW(LogCategory::kSecurity,               “Autofill decryption failed: ” + result.UnwrapErr().message);     return “”;   }   return result.Unwrap(); }  } // namespace  AutofillStoreImpl::AutofillStoreImpl(IStorageEngine* storage,                                      ICryptoVault* crypto)     : storage_(storage), crypto_(crypto) {   DCHECK(storage_);   DCHECK(crypto_);   InitSchema();   InitEncryptionKey(); }  AutofillStoreImpl::~AutofillStoreImpl() = default;  void AutofillStoreImpl::InitSchema() {   int version = storage_->GetVersion();   if (version < kSchemaVersion) {     storage_->Execute(         “CREATE TABLE IF NOT EXISTS autofill_profiles (”         “  id INTEGER PRIMARY KEY AUTOINCREMENT,”         “  name_full TEXT,”         “  name_first TEXT,”         “  name_last TEXT,”         “  email TEXT,”         “  phone TEXT,”         “  address_line1 TEXT,”         “  address_line2 TEXT,”         “  city TEXT,”         “  state TEXT,”         “  postal_code TEXT,”         “  country TEXT,”         “  created_at INTEGER,”         “  last_used INTEGER”         “)”);      storage_->Execute(         “CREATE TABLE IF NOT EXISTS autofill_credit_cards (”         “  id INTEGER PRIMARY KEY AUTOINCREMENT,”         “  cardholder_name TEXT,”         “  number_encrypted BLOB,”         “  expiry_month TEXT,”         “  expiry_year TEXT,”         “  cvv_encrypted BLOB,”         “  created_at INTEGER,”         “  last_used INTEGER”         “)”);      storage_->Execute(         “CREATE TABLE IF NOT EXISTS autofill_passwords (”         “  id INTEGER PRIMARY KEY AUTOINCREMENT,”         “  origin TEXT NOT NULL,”         “  username TEXT,”         “  password_encrypted BLOB,”         “  created_at INTEGER,”         “  last_used INTEGER”         “)”);      storage_->Execute(         “CREATE INDEX IF NOT EXISTS idx_passwords_origin ON autofill_passwords(origin)”);      storage_->Migrate(kSchemaVersion);     VEOR_LOGI(LogCategory::kInfrastructure, “Autofill schema initialized”);   } }  void AutofillStoreImpl::InitEncryptionKey() {   auto key_result = crypto_->RetrieveSecret(“veor_autofill_key”);   if (key_result.IsOk()) {     encryption_key_ = key_result.Unwrap();   } else {     auto gen_result = crypto_->GenerateRandom(32);     if (gen_result.IsOk()) {       encryption_key_ = gen_result.Unwrap();       crypto_->StoreSecret(“veor_autofill_key”, encryption_key_);     } else {       VEOR_LOGW(LogCategory::kSecurity,                 “Failed to generate autofill encryption key”);     }   } }  // ── Profiles ─────────────────────────────────────────────────────────────────  Result<std::vector<AutofillProfile>, std::string> AutofillStoreImpl::GetProfiles() {   std::vector<AutofillProfile> profiles;   auto stmt_result = storage_->Prepare(       “SELECT id, name_full, name_first, name_last, email, phone, ”       “address_line1, address_line2, city, state, postal_code, country, ”       “created_at, last_used FROM autofill_profiles ORDER BY last_used DESC”);   if (stmt_result.IsErr()) {     return Result<std::vector<AutofillProfile>, std::string>::Err(         stmt_result.UnwrapErr().ToString());   }    auto stmt = std::move(stmt_result).Unwrap();   while (true) {     auto step = stmt->Step();     if (step.IsErr())       break;     if (!step.Unwrap())       break;      AutofillProfile p;     p.id = stmt->GetInt64(0);     p.name_full = stmt->GetString(1);     p.name_first = stmt->GetString(2);     p.name_last = stmt->GetString(3);     p.email = stmt->GetString(4);     p.phone = stmt->GetString(5);     p.address_line1 = stmt->GetString(6);     p.address_line2 = stmt->GetString(7);     p.city = stmt->GetString(8);     p.state = stmt->GetString(9);     p.postal_code = stmt->GetString(10);     p.country = stmt->GetString(11);     p.created_at = base::Time::UnixEpoch() +         base::Microseconds(stmt->GetInt64(12));     p.last_used = base::Time::UnixEpoch() +         base::Microseconds(stmt->GetInt64(13));     profiles.push_back(p);   }    return Result<std::vector<AutofillProfile>, std::string>::Ok(       std::move(profiles)); }  Result<void, std::string> AutofillStoreImpl::SaveProfile(     const AutofillProfile& profile) {   int64_t now = (base::Time::Now() - base::Time::UnixEpoch()).InMicroseconds();   auto stmt_result = storage_->Prepare(       “INSERT INTO autofill_profiles (name_full, name_first, name_last, ”       “email, phone, address_line1, address_line2, city, state, postal_code, ”       “country, created_at, last_used) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)”);   if (stmt_result.IsErr()) {     return Result<void, std::string>::Err(stmt_result.UnwrapErr().ToString());   }    auto stmt = std::move(stmt_result).Unwrap();   stmt->BindString(1, profile.name_full);   stmt->BindString(2, profile.name_first);   stmt->BindString(3, profile.name_last);   stmt->BindString(4, profile.email);   stmt->BindString(5, profile.phone);   stmt->BindString(6, profile.address_line1);   stmt->BindString(7, profile.address_line2);   stmt->BindString(8, profile.city);   stmt->BindString(9, profile.state);   stmt->BindString(10, profile.postal_code);   stmt->BindString(11, profile.country);   stmt->BindInt64(12, now);   stmt->BindInt64(13, now);    auto step = stmt->Step();   if (step.IsErr()) {     return Result<void, std::string>::Err(step.UnwrapErr().ToString());   }    return Result<void, std::string>::Ok(); }  Result<void, std::string> AutofillStoreImpl::DeleteProfile(int64_t id) {   auto result = storage_->Execute(“DELETE FROM autofill_profiles WHERE id = ?”,                                   {std::to_string(id)});   if (result.IsErr()) {     return Result<void, std::string>::Err(result.UnwrapErr().ToString());   }   return Result<void, std::string>::Ok(); }  // ── Credit Cards ───────────────────────────────────────────────────────────────  Result<std::vector<CreditCard>, std::string> AutofillStoreImpl::GetCreditCards() {   std::vector<CreditCard> cards;   auto stmt_result = storage_->Prepare(       “SELECT id, cardholder_name, number_encrypted, expiry_month, ”       “expiry_year, cvv_encrypted, created_at, last_used ”       “FROM autofill_credit_cards ORDER BY last_used DESC”);   if (stmt_result.IsErr()) {     return Result<std::vector<CreditCard>, std::string>::Err(         stmt_result.UnwrapErr().ToString());   }    auto stmt = std::move(stmt_result).Unwrap();   while (true) {     auto step = stmt->Step();     if (step.IsErr())       break;     if (!step.Unwrap())       break;      CreditCard c;     c.id = stmt->GetInt64(0);     c.cardholder_name = stmt->GetString(1);     c.number_encrypted = DecryptField(crypto_, stmt->GetString(2), encryption_key_);     c.expiry_month = stmt->GetString(3);     c.expiry_year = stmt->GetString(4);     c.cvv_encrypted = DecryptField(crypto_, stmt->GetString(5), encryption_key_);     c.created_at = base::Time::UnixEpoch() +         base::Microseconds(stmt->GetInt64(6));     c.last_used = base::Time::UnixEpoch() +         base::Microseconds(stmt->GetInt64(7));     cards.push_back(c);   }    return Result<std::vector<CreditCard>, std::string>::Ok(std::move(cards)); }  Result<void, std::string> AutofillStoreImpl::SaveCreditCard(     const CreditCard& card) {   int64_t now = (base::Time::Now() - base::Time::UnixEpoch()).InMicroseconds();   std::string enc_number = EncryptField(crypto_, card.number_encrypted, encryption_key_);   std::string enc_cvv = EncryptField(crypto_, card.cvv_encrypted, encryption_key_);    auto stmt_result = storage_->Prepare(       “INSERT INTO autofill_credit_cards (cardholder_name, number_encrypted, ”       “expiry_month, expiry_year, cvv_encrypted, created_at, last_used) ”       “VALUES (?, ?, ?, ?, ?, ?, ?)”);   if (stmt_result.IsErr()) {     return Result<void, std::string>::Err(stmt_result.UnwrapErr().ToString());   }    auto stmt = std::move(stmt_result).Unwrap();   stmt->BindString(1, card.cardholder_name);   stmt->BindString(2, enc_number);   stmt->BindString(3, card.expiry_month);   stmt->BindString(4, card.expiry_year);   stmt->BindString(5, enc_cvv);   stmt->BindInt64(6, now);   stmt->BindInt64(7, now);    auto step = stmt->Step();   if (step.IsErr()) {     return Result<void, std::string>::Err(step.UnwrapErr().ToString());   }    return Result<void, std::string>::Ok(); }  Result<void, std::string> AutofillStoreImpl::DeleteCreditCard(int64_t id) {   auto result = storage_->Execute(       “DELETE FROM autofill_credit_cards WHERE id = ?”, {std::to_string(id)});   if (result.IsErr()) {     return Result<void, std::string>::Err(result.UnwrapErr().ToString());   }   return Result<void, std::string>::Ok(); }  // ── Passwords ──────────────────────────────────────────────────────────────────  Result<std::vector<PasswordEntry>, std::string> AutofillStoreImpl::GetPasswordsForOrigin(const std::string& origin) {   std::vector<PasswordEntry> entries;   auto stmt_result = storage_->Prepare(       “SELECT id, origin, username, password_encrypted, created_at, last_used ”       “FROM autofill_passwords WHERE origin = ? ORDER BY last_used DESC”);   if (stmt_result.IsErr()) {     return Result<std::vector<PasswordEntry>, std::string>::Err(         stmt_result.UnwrapErr().ToString());   }    auto stmt = std::move(stmt_result).Unwrap();   stmt->BindString(1, origin);    while (true) {     auto step = stmt->Step();     if (step.IsErr())       break;     if (!step.Unwrap())       break;      PasswordEntry e;     e.id = stmt->GetInt64(0);     e.origin = stmt->GetString(1);     e.username = stmt->GetString(2);     e.password_encrypted = DecryptField(crypto_, stmt->GetString(3), encryption_key_);     e.created_at = base::Time::UnixEpoch() +         base::Microseconds(stmt->GetInt64(4));     e.last_used = base::Time::UnixEpoch() +         base::Microseconds(stmt->GetInt64(5));     entries.push_back(e);   }    return Result<std::vector<PasswordEntry>, std::string>::Ok(std::move(entries)); }  Result<void, std::string> AutofillStoreImpl::SavePassword(     const PasswordEntry& entry) {   // Delete existing entry for same origin + username   storage_->Execute(       “DELETE FROM autofill_passwords WHERE origin = ? AND username = ?”,       {entry.origin, entry.username});    int64_t now = (base::Time::Now() - base::Time::UnixEpoch()).InMicroseconds();   std::string enc_password = EncryptField(crypto_, entry.password_encrypted, encryption_key_);    auto stmt_result = storage_->Prepare(       “INSERT INTO autofill_passwords (origin, username, password_encrypted, ”       “created_at, last_used) VALUES (?, ?, ?, ?, ?)”);   if (stmt_result.IsErr()) {     return Result<void, std::string>::Err(stmt_result.UnwrapErr().ToString());   }    auto stmt = std::move(stmt_result).Unwrap();   stmt->BindString(1, entry.origin);   stmt->BindString(2, entry.username);   stmt->BindString(3, enc_password);   stmt->BindInt64(4, now);   stmt->BindInt64(5, now);    auto step = stmt->Step();   if (step.IsErr()) {     return Result<void, std::string>::Err(step.UnwrapErr().ToString());   }    return Result<void, std::string>::Ok(); }  Result<void, std::string> AutofillStoreImpl::DeletePassword(int64_t id) {   auto result = storage_->Execute(       “DELETE FROM autofill_passwords WHERE id = ?”, {std::to_string(id)});   if (result.IsErr()) {     return Result<void, std::string>::Err(result.UnwrapErr().ToString());   }   return Result<void, std::string>::Ok(); }  } // namespace veor
